args.new_string:
/**
 * 算总价。跨档位要**分段累加**：
 * 每一档只按落入该档的公斤数计价，而不是整单按最终档的单价算。
 * 例：total(8) = 1×18 + 4×15 + 3×12 = 114。
 */
export function total(kg) {
  if (!tierOf(kg)) return Infinity; // 超出最大档（>20kg）仍是设计内的 Infinity
  let sum = 0;
  let lower = 0; // 当前档的下界（上一档的 maxKg）
  for (const t of TIERS) {
    if (kg <= lower) break; // 本公斤数已在此档之前用完
    const kgInTier = Math.min(kg, t.maxKg) - lower; // 落入本档的公斤数
    sum += kgInTier * t.perKg;
    lower = t.maxKg;
  }
  return sum;
}

